#!/usr/bin/env python3
"""Review-only, deny-by-default PDF intake preflight. Never opens or extracts PDFs.

Usage: python mira_intake_preflight.py --inventory pdfs.json --manifest extraction.jsonl --approved approved.json

inventory: [{"path": "30SEP_PAPER_DUMP/name.pdf", "blob_sha": "..."}, ...]
approved: [{"path": "...", "blob_sha": "...", "reviewer": "...", "citation": "...",
            "author_checked": true, "restriction_checked": true, "approved": true}, ...]

No entry is admitted from a path name alone. Git blob SHA is a change detector, not a PDF
content SHA256 or an author identification. The restricted-name heuristic is a veto,
not an author-safety guarantee.
"""
import argparse, json, re
from pathlib import PurePosixPath

BANNED = re.compile(r"schreiber|hypothesis[\s_\-.]*h(?:\b|[\s_\-.])", re.I)
BANNED_PARTS = {'prior_art'}  # conservative until explicitly curated

def valid_path(path):
    if not isinstance(path, str) or not path.startswith('30SEP_PAPER_DUMP/'):
        return False
    p = PurePosixPath(path)
    return ('..' not in p.parts and not path.startswith('/') and
            path.endswith('.pdf') and not any(x.casefold() in BANNED_PARTS for x in p.parts))

def audit(inventory, prior, approved):
    records = {r['source_path'] for r in prior if 'source_path' in r}
    allow = {}
    duplicates = set()
    for a in approved:
        p=a.get('path')
        if p in allow:
            duplicates.add(p)
        allow[p]=a
    result=[]
    for f in inventory:
        p=f.get('path',''); blob=f.get('blob_sha')
        if p in records:
            status='ALREADY_RECORDED'
        elif not valid_path(p):
            status='DENY_PATH'
        elif BANNED.search(p):
            status='DENY_RESTRICTED_FILENAME'
        elif p in duplicates:
            status='DENY_DUPLICATE_ATTESTATION'
        else:
            a=allow.get(p,{})
            ok=(a.get('approved') is True and a.get('author_checked') is True and
                a.get('restriction_checked') is True and a.get('blob_sha') == blob and
                bool(str(a.get('citation','')).strip()) and
                bool(str(a.get('reviewer','')).strip()))
            status='ELIGIBLE_FOR_CONTROLLED_EXTRACTION' if ok else 'HOLD_REVIEW_REQUIRED'
        result.append({'path':p,'blob_sha':blob,'decision':status})
    return result

def main():
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--inventory',required=True)
    ap.add_argument('--manifest',required=True)
    ap.add_argument('--approved',required=True)
    ap.add_argument('--out')
    a=ap.parse_args()
    inventory=json.load(open(a.inventory,encoding='utf8'))
    prior=[json.loads(s) for s in open(a.manifest,encoding='utf8') if s.strip()]
    approved=json.load(open(a.approved,encoding='utf8'))
    results=audit(inventory,prior,approved)
    from collections import Counter
    print(json.dumps(dict(Counter(x['decision'] for x in results)),indent=2))
    if a.out:
        with open(a.out,'w',encoding='utf8') as out:
            json.dump(results,out,indent=2)

if __name__=='__main__': main()
