import unittest
from mira_intake_preflight import audit
class GateTests(unittest.TestCase):
 def setUp(self):
  self.p='30SEP_PAPER_DUMP/eligible.pdf'
  self.f=[{'path':self.p,'blob_sha':'abc'}]
  self.a=[{'path':self.p,'blob_sha':'abc','approved':True,'author_checked':True,'restriction_checked':True,'reviewer':'reviewer','citation':'DOI:example'}]
 def decision(self,files=None,approved=None,manifest=None):
  return audit(self.f if files is None else files,[] if manifest is None else manifest,self.a if approved is None else approved)[0]['decision']
 def test_allow_only_with_all_attestations(self): self.assertEqual(self.decision(),'ELIGIBLE_FOR_CONTROLLED_EXTRACTION')
